package com.prima.factory.device.simulator; import com.prima.factory.domain.*;
public record TelemetryState(long count,double cycle,double load,double current,double temperature,EquipmentStatus operating,CommunicationStatus communication){ public TelemetryState next(RandomSource r){boolean running=operating==EquipmentStatus.RUNNING&&communication==CommunicationStatus.CONNECTED;return new TelemetryState(count+(running&&r.nextDouble()<.25?1:0),clamp(cycle+(r.nextDouble()-.5)*.2,8,30),clamp(load+(r.nextDouble()-.5)*2,15,95),clamp(current+(r.nextDouble()-.5),2,30),clamp(temperature+(r.nextDouble()-.5)*.3,25,80),operating,communication);}private static double clamp(double v,double min,double max){return Math.max(min,Math.min(max,v));}}
